class R{String s(boolean p,String[]I){long x=0,y=0,a=0,e=0;for(var L:I){var w=L.split(" ");int d=p?"RDLU".indexOf(w[0]):w[2].charAt(7)%4,n=p?new Integer(w[1]):Integer.parseInt(w[2].substring(2,7),16);long X=x+(d%2<1?1-d:0)*n,Y=y+(d%2>0?2-d:0)*n;a+=x*Y-X*y;e+=n;x=X;y=Y;}return(Math.abs(a)+e)/2+1+"";}}
